output_text:
[
  {
    "id": "no_cart_single_file_aisle",
    "text": "Shopping carts are prohibited in single-file aisles, identified by a horizontal free width of one cell.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cart_in_single_file_aisle": {
          "and": [
            "hasCart",
            "single_file_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_single_file_aisle"
    }
  },
  {
    "id": "no_cart_between_facing_shelves",
    "text": "Shopping carts are prohibited in narrow shelf canyons where shelves face the agent from both east and west.",
    "abstraction": {
      "state_properties": {
        "between_facing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "cart_between_facing_shelves": {
          "and": [
            "hasCart",
            "between_facing_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_between_facing_shelves"
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "An agent must not push a cart into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "hand_carry_only_upper_shelf_items",
    "text": "Shelf interactions inside single-file shelf aisles must be done without the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "hand_carry_shelf_zone": {
          "and": [
            "single_file_aisle",
            "adjShelf"
          ]
        },
        "cart_interaction_in_hand_carry_zone": {
          "and": [
            "hasCart",
            "INTERACT",
            "hand_carry_shelf_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_interaction_in_hand_carry_zone"
    }
  },
  {
    "id": "drop_cart_only_in_wide_parking_area",
    "text": "Carts may only be parked or dropped in wide, unobstructed aisle areas rather than beside shelves or in tight passages.",
    "abstraction": {
      "state_properties": {
        "wide_unobstructed_cart_parking_area": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "wide_unobstructed_cart_parking_area"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking or dropping a cart, the agent is obliged to retrieve a cart before the end of the shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "drop_cart",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "return_to_cart_after_hand_carry_item",
    "text": "After taking an item from a single-file shelf aisle, the agent is obliged to return to and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "hand_carry_shelf_zone": {
          "and": [
            "single_file_aisle",
            "adjShelf"
          ]
        }
      },
      "events": {
        "hand_carry_shelf_interaction": {
          "pre": {
            "and": [
              "hand_carry_shelf_zone",
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "hand_carry_shelf_interaction",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "cart_required_for_normal_shelf_access",
    "text": "Shelf interactions in normal-width shopping aisles require the agent to have the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "normal_width_shelf_zone": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_aisle"
            }
          ]
        },
        "normal_shelf_interaction_without_cart": {
          "and": [
            "normal_width_shelf_zone",
            "INTERACT",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "normal_shelf_interaction_without_cart"
    }
  }
]
